Este código de un formulario de búsqueda tiene 4 errores: los usuarios dicen que no aparecen resultados, que la página va lenta y que algunos botones dejan de funcionar. Encuéntralos y explica cómo arreglarlos.

```
async function search(query) {
  const results = await fetch("/api/search?q=" + query);
  displayResults(results);
}

let debounceTimer;
function onInput(e) {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(search(e.target.value), 300);
}

function displayResults(data) {
  const container = document.getElementById("results");
  data.forEach(item => {
    container.innerHTML += `<div>${item.name}</div>`;
  });
}

document.querySelector(".search").addEventListener("click", onInput);
```

Este código funciona pero es muy lento con datos grandes. Identifica los problemas de rendimiento y reescribe las funciones optimizadas:

```python
# Función 1: Buscar duplicados (O(n²) actual)
def find_duplicates(items):
    duplicates = []
    for i in range(len(items)):
        for j in range(i+1, len(items)):
            if items[i] == items[j] and items[i] not in duplicates:
                duplicates.append(items[i])
    return duplicates

# Función 2: Contar palabras en archivo (lee todo en memoria)
def count_words(filename):
    content = open(filename).read()
    words = content.split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] = word_count[word] + 1
        else:
            word_count[word] = 1
    return word_count
```

Un compañero ha abierto un pull request con el formulario de alta de clientes. Soporte dice que a veces se guarda el correo que había antes de corregirlo y que, si se cambia rápido de cliente, aparecen los datos del anterior.

```jsx
function FichaCliente({ id }) {
  const [cliente, setCliente] = useState({});
  const [email, setEmail] = useState("");

  useEffect(() => {
    fetch(`/api/clientes/${id}`).then(r => r.json()).then(setCliente);
  }, []);

  function guardar() {
    setEmail(email.trim());
    fetch("/api/clientes/" + id, { method: "PUT", body: JSON.stringify({ ...cliente, email }) });
  }

  return <input value={email} onChange={e => setEmail(e.target.value)} onBlur={guardar} />;
}
```

